#!/usr/bin/env python3
"""Properly parse chem_comp loop from each CIF (quote-aware) and list nonstandard components."""
import glob

def split_mmcif_line(line):
    """Split an mmCIF data line into fields, respecting single quotes."""
    fields = []
    cur = []
    i = 0
    n = len(line)
    while i < n:
        c = line[i]
        if c == "'":
            # find closing quote (double '' is escaped quote)
            i += 1
            while i < n:
                if line[i] == "'":
                    if i + 1 < n and line[i+1] == "'":
                        cur.append("'")
                        i += 2
                        continue
                    i += 1
                    break
                cur.append(line[i])
                i += 1
            fields.append(''.join(cur))
            cur = []
        elif c.isspace():
            if cur:
                fields.append(''.join(cur))
                cur = []
            i += 1
        else:
            cur.append(c)
            i += 1
    if cur:
        fields.append(''.join(cur))
    return fields

for path in sorted(glob.glob('/app/cif/*.cif')):
    pid = path.split('/')[-1].replace('.cif', '')
    lines = open(path).read().splitlines()
    print(f'=== {pid} ===')
    for i, ln in enumerate(lines):
        if ln.strip() == 'loop_':
            # gather header
            headers = []
            j = i + 1
            while j < len(lines) and lines[j].strip().startswith('_'):
                headers.append(lines[j].strip().split()[0])
                j += 1
            if '_chem_comp.id' in headers:
                while j < len(lines) and lines[j].strip() and not lines[j].startswith(('loop_', 'data_', '#')):
                    f = split_mmcif_line(lines[j])
                    d = dict(zip(headers, f))
                    typ = d.get('_chem_comp.type', '')
                    nstd = d.get('_chem_comp.mon_nstd_flag', '')
                    if typ in ('non-polymer', 'OTHER', '') or (nstd == 'n'):
                        print(f"  {d.get('_chem_comp.id','?'):6s} | {typ:15s} | nstd={nstd} | {d.get('_chem_comp.name','?')[:70]} | {d.get('_chem_comp.formula','?')}")
                break

