#!/usr/bin/env python3
"""Submit BLASTp of antibody chains against PDB via EBI REST API."""
import urllib.request
import urllib.parse
import time

def read_fasta(path):
    seqs = {}
    name = None
    buf = []
    for line in open(path):
        line = line.rstrip()
        if line.startswith('>'):
            if name:
                seqs[name] = ''.join(buf)
            name = line[1:].strip()
            buf = []
        elif line:
            buf.append(line)
    if name:
        seqs[name] = ''.join(buf)
    return seqs

seqs = read_fasta('/app/antibody.fasta')
for name, seq in seqs.items():
    print(name, len(seq))

heavy = seqs['heavy chain']
params = urllib.parse.urlencode({
    'program': 'blastp',
    'database': 'pdb_sequences',
    'query_data': heavy,
}).encode()
req = urllib.request.Request('https://www.ebi.ac.uk/Tools/services/rest/blast/search',
                             data=params, headers={'User-Agent': 'Mozilla/5.0'})
job = urllib.request.urlopen(req, timeout=120).read().decode()
print('job id:', job)
open('/app/blast_job.txt', 'w').write(job)

# poll
for _ in range(60):
    time.sleep(10)
    s = urllib.request.urlopen('https://www.ebi.ac.uk/Tools/services/rest/blast/status/' + job, timeout=60).read().decode()
    print('status:', s)
    if s in ('FINISHED', 'FAILED', 'UNKNOWN'):
        break
if s == 'FINISHED':
    xml = urllib.request.urlopen('https://www.ebi.ac.uk/Tools/services/rest/blast/report/' + job + '/xml', timeout=120).read().decode()
    open('/app/blast_result.xml', 'w').write(xml)
    print('saved result, length', len(xml))

