#!/usr/bin/env python3
"""RCSB sequence search (correct schema) for the antibody chains."""
import json
import urllib.request
import urllib.error

def read_fasta(path):
    seqs = {}
    name = None
    buf = []
    for line in open(path):
        line = line.rstrip()
        if line.startswith('>'):
            if name:
                seqs[name] = ''.join(buf)
            name = line[1:].strip()
            buf = []
        elif line:
            buf.append(line)
    if name:
        seqs[name] = ''.join(buf)
    return seqs

def seq_query(seq, cutoff=95, rows=50):
    q = {
        'query': {
            'type': 'terminal',
            'service': 'sequence',
            'parameters': {
                'evalue_cutoff': 1,
                'identity_cutoff': cutoff,
                'sequence_type': 'protein',
                'value': seq,
            },
        },
        'return_type': 'polymer_entity',
        'request_options': {
            'paginate': {'start': 0, 'rows': rows},
            'scoring_strategy': 'sequence',
        },
    }
    data = json.dumps(q).encode()
    req = urllib.request.Request('https://search.rcsb.org/rcsbsearch/v2/query', data=data,
                                 headers={'Content-Type': 'application/json', 'User-Agent': 'Mozilla/5.0'})
    try:
        return json.loads(urllib.request.urlopen(req, timeout=180).read().decode())
    except urllib.error.HTTPError as e:
        return {'HTTP_ERROR': e.code, 'body': e.read().decode()[:600]}

seqs = read_fasta('/app/antibody.fasta')
for name in ('heavy chain', 'light chain'):
    seq = seqs[name]
    print(f'##### {name} (identity >= 95%) #####')
    r = seq_query(seq)
    if 'HTTP_ERROR' in r:
        print(r)
        continue
    print('total count:', r.get('total_count'))
    for res in r.get('result_set', []):
        print('  ', res.get('identifier'), '| score:', res.get('score'))
    print()

